This C application generates and renders a complete 12-month calendar for any given year. It calculates starting weekdays for each month and handles leap years using Zeller's congruence principles.

## C Calendar Source Code

```c


#define _CRT_SECURE_NO_WARNINGS
#define TRUE 1
#define FALSE 0

#include <stdio.h>
#include <conio.h>
#include <stdlib.h>
#include <time.h>

int get_year(void)
{
     int year = -1;
     printf("Type a year : ");
     scanf("%d", &year);
     if (year == -1)
     {
           time_t rawtime;
           struct tm * timeinfo;
           time(&rawtime);
           timeinfo = localtime(&rawtime);
           year = timeinfo->tm_year + 1900;
     }
     return year;
}

int get_day_code(int year)
{
     int day_code;
     int x1, x2, x3;

     x1 = (year - 1.) / 4.0;
     x2 = (year - 1.) / 100.;
     x3 = (year - 1.) / 400.;
     day_code = (year + x1 - x2 + x3) % 7;

     return day_code;
}

/*
simple algorithm to know a year is leap or not can be defined as follows
if (year is not divisible by 4) then(it is a common year)
else if (year is not divisible by 100) then(it is a leap year)
else if (year is not divisible by 400) then(it is a common year)
else (it is a leap year)
*/
int get_leap_year(int year)
{
     if (((year % 4 == 0) && (year % 100 != 0)) || (year % 400 == 0))
           return TRUE;
     else
           return FALSE;
}

void print_calendar(int year, int day_code, int leap_year) //function header
{
     int days_in_month;   /* number of days in month currently being printed */
     int day;             /* counter for day of month */
     int month;           /* month = 1 is Jan, month = 2 is Feb, etc. */

     printf("\t\t\t\t%d", year);

     for (month = 1; month <= 12; month++)
     {
           switch (month)
           {
                /* print name and set days_in_month */
           case 1:
                printf("\n\nJanuary");
                days_in_month = 31;
                break;
           case 2:
                printf("\n\nFebruary");
                days_in_month = leap_year ? 29 : 28;
                break;
           case 3:
                printf("\n\nMarch");
                days_in_month = 31;
                break;
           case 4:
                printf("\n\nApril");
                days_in_month = 30;
                break;
           case 5:
                printf("\n\nMay");
                days_in_month = 31;
                break;
           case 6:
                printf("\n\nJune");
                days_in_month = 30;
                break;
           case 7:
                printf("\n\nJuly");
                days_in_month = 31;
                break;
           case 8:
                printf("\n\nAugust");
                days_in_month = 31;
                break;
           case 9:
                printf("\n\nSeptember");
                days_in_month = 30;
                break;
           case 10:
                printf("\n\nOctober");
                days_in_month = 31;
                break;
           case 11:
                printf("\n\nNovember");
                days_in_month = 30;
                break;
           case 12:
                printf("\n\nDecember");
                days_in_month = 31;
                break;
           }

           printf("\n\nSun\tMon\tTue\tWed\tThu\tFri\tSat\n");

           /* advance printer to correct position for first date */
           for (day = 1; day < day_code + 1; day++)
                printf("\t");

           /* print the dates for one month */
           for (day = 1; day <= days_in_month; day++)
           {
                printf("%2d", day);
                if ((day + day_code) % 7 > 0) /* before Sat? */
                     /* move to next day in same week */
                     printf("\t");
                else if (day != days_in_month)
                     /* skip to next line to start with Sun */
                     printf("\n");
           }

           /* set day_code for next month to begin */
           day_code = (day_code + days_in_month) % 7;
     }
}

int main()
{
     int year, day_code, leap_year;
     year = get_year();
     day_code = get_day_code(year);
     leap_year = get_leap_year(year);
     print_calendar(year, day_code, leap_year);

     _getch();
     return 0;
}
```

## Algorithm & Calculations

- **Leap Year Check**: Determines whether February has 28 or 29 days based on the rule `(year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)`.
- **First Day Offset**: Calculates the day of the week for January 1st to align the calendar grid columns accurately.

## Overview

Directory surveillance allows an application to detect file creations, deletions, renames, and modifications in real time. In Windows, this is achieved natively using the Win32 `ReadDirectoryChangesW` API.

## C++ Directory Monitor Implementation

```cpp


#define _CRT_SECURE_NO_WARNINGS
#include <Windows.h>
#include <stdio.h>
#include <tchar.h>
#include <iostream>
#include <string>

#define MAX_DIRS 25
#define MAX_FILES 255
#define MAX_BUFFER 4096

extern "C" {
     WINBASEAPI BOOL WINAPI
           ReadDirectoryChangesW(HANDLE hDirectory,
           LPVOID lpBuffer, DWORD nBufferLength,
           BOOL bWatchSubtree, DWORD dwNotifyFilter,
           LPDWORD lpBytesReturned,
           LPOVERLAPPED lpOverlapped,
           LPOVERLAPPED_COMPLETION_ROUTINE lpCompletionRoutine
           );
}
// all purpose structure to contain directory information and provide
// the input buffer that is filled with file change data

typedef struct _DIRECTORY_INFO {
     HANDLE hDir;
     TCHAR lpszDirName[MAX_PATH];
     CHAR lpBuffer[MAX_BUFFER];
     DWORD dwBufLength;
     OVERLAPPED Overlapped;
}DIRECTORY_INFO, *PDIRECTORY_INFO, *LPDIRECTORY_INFO;

DIRECTORY_INFO DirInfo[MAX_DIRS];   // Buffer for of the directory

void WatchDirectory(LPCWSTR path)
{
     char buf[2048];
     DWORD nRet;
     BOOL result = TRUE;
     char filename[MAX_PATH];
     DirInfo[0].hDir = CreateFileW(
           path,
           GENERIC_READ | FILE_LIST_DIRECTORY,
           FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
           NULL,
           OPEN_EXISTING,
           FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OVERLAPPED,
           NULL
           );

     if (DirInfo[0].hDir == INVALID_HANDLE_VALUE)
     {
           return; //cannot open folder
     }

     lstrcpy(DirInfo[0].lpszDirName, path);

     OVERLAPPED PollingOverlap;
     FILE_NOTIFY_INFORMATION* pNotify;
     int offset;
     PollingOverlap.OffsetHigh = 0;

     PollingOverlap.hEvent = CreateEvent(NULL, TRUE, FALSE, NULL);

     while (result)
     {
           result = ReadDirectoryChangesW(
                DirInfo[0].hDir,// handle to the directory to be watched
                &buf,// pointer to the buffer to receive the read results
                sizeof(buf),// length of lpBuffer
                TRUE,// flag for monitoring directory or directory tree
                FILE_NOTIFY_CHANGE_FILE_NAME |
                FILE_NOTIFY_CHANGE_DIR_NAME |
                FILE_NOTIFY_CHANGE_SIZE |
                FILE_NOTIFY_CHANGE_LAST_WRITE |
                FILE_NOTIFY_CHANGE_LAST_ACCESS |
                FILE_NOTIFY_CHANGE_CREATION,
                &nRet,// number of bytes returned
                &PollingOverlap,// pointer to structure needed for overlapped I/O
                NULL);

           WaitForSingleObject(PollingOverlap.hEvent, INFINITE);

           offset = 0;
           int rename = 0;

           do
           {
                pNotify = (FILE_NOTIFY_INFORMATION*)((char*)buf + offset);
                strcpy(filename, "");
                int filenamelen = WideCharToMultiByte(
                     CP_ACP,
                     0,
                     pNotify->FileName,
                     pNotify->FileNameLength / 2,
                     filename,
                     sizeof(filename),
                     NULL,
                     NULL
                     );

                //filename[pNotify->FileNameLength / 2] = ` `;

                for (size_t i = pNotify->FileNameLength / 2; i < 260; i++)
                {
                     filename[i] = '\0';
                }

                switch (pNotify->Action)
                {
                case FILE_ACTION_ADDED:
                     printf("\nThe file is added to the directory: [%s] \n", filename);
                     break;
                case FILE_ACTION_REMOVED:
                     printf("\nThe file is removed from the directory: [%s] \n", filename);
                     break;
                case FILE_ACTION_MODIFIED:
                     printf("\nThe file is modified. This can be a change in the time stamp or attributes: [%s]\n", filename);
                     break;
                case FILE_ACTION_RENAMED_OLD_NAME:
                     printf("\nThe file was renamed and this is the old name: [%s]\n", filename);
                     break;
                case FILE_ACTION_RENAMED_NEW_NAME:
                     printf("\nThe file was renamed and this is the new name: [%s]\n", filename);
                     break;
                default:
                     printf("\nDefault error.\n");
                     break;
                }

                offset += pNotify->NextEntryOffset;
           } while (pNotify->NextEntryOffset); //(offset != 0);
     }

     CloseHandle(DirInfo[0].hDir);
}

int main()
{
     WatchDirectory(L"c:\\");
     return 0;
}
```

## Win32 Directory Watching APIs

- **`CreateFile`**: Opens a directory handle with `FILE_LIST_DIRECTORY` permissions.
- **`ReadDirectoryChangesW`**: Waits for filesystem change notifications within the specified directory buffer.
- **`FILE_NOTIFY_INFORMATION`**: Structure containing notification action flags (`FILE_ACTION_ADDED`, `FILE_ACTION_REMOVED`, `FILE_ACTION_MODIFIED`).

## Overview

This program demonstrates a retro 7-segment digital LED clock created in C++ using the Win32 GDI API. The display simulates illuminated digital segments on a dark background, refreshing synchronously on timer ticks.

## Win32 Digital Clock Source Code

```cpp


#include <windows.h>
#define ID_TIMER    1

LRESULT CALLBACK WndProc(HWND, UINT, WPARAM, LPARAM);

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, PSTR szCmdLine, int iCmdShow)
{
     static TCHAR szAppName[] = TEXT("DigClock");
