void DisplayTwoDigits(HDC hdc, int iNumber, BOOL fSuppress)
{
     if (!fSuppress || (iNumber / 10 != 0))
           DisplayDigit(hdc, iNumber / 10);
     OffsetWindowOrgEx(hdc, -42, 0, NULL);
     DisplayDigit(hdc, iNumber % 10);
